package com.aigora.tutororchestrator.application.usecase;
import com.aigora.tutororchestrator.application.ports.LearningSessionRepository; import com.aigora.tutororchestrator.domain.model.*; import com.aigora.tutororchestrator.domain.valueobjects.*; import java.util.*;
public final class LearningSessionRecoveryCoordinator { private final LearningSessionRepository repo; public LearningSessionRecoveryCoordinator(LearningSessionRepository repo){this.repo=repo;} public RecoveryAction actionFor(LearningSessionId id){var s=repo.findById(id).orElseThrow(()->new IllegalArgumentException("Learning session not found")); return switch(s.status()){case AWAITING_ASSESSMENT->RecoveryAction.REQUEST_ASSESSMENT;case PROCESSING_DECISION->RecoveryAction.REQUEST_ORCHESTRATION_DECISION;default->RecoveryAction.NONE;};} public List<LearningSessionId> recoverableSessions(){var ids=new ArrayList<LearningSessionId>();repo.findByStatus(LearningSessionStatus.AWAITING_ASSESSMENT).forEach(s->ids.add(s.id()));repo.findByStatus(LearningSessionStatus.PROCESSING_DECISION).forEach(s->ids.add(s.id()));return List.copyOf(ids);} }
